(function () {
  var S = window.CardSets && window.CardSets.get('iconic-dishes');
  if (!S) return;
  var extra = [{"name":"Tacos al Pastor","rarity":"chase","id":"tacos-al-pastor","subtitle":"Latin & Caribbean","details":"Marinated pork shaved from a vertical spit, served on corn tortillas with pineapple, onion and coriander, bright and smoky-sweet.","image":"https://upload.wikimedia.org/wikipedia/commons/0/07/Tacos_al_pastor%2C_taco_de_panza.jpg"},{"name":"Mission Burrito","rarity":"legendary","id":"mission-burrito","subtitle":"Latin & Caribbean","details":"A large flour tortilla wrapped around rice, beans, salsa, cheese and grilled meat, a hearty style associated with San Francisco.","image":"https://upload.wikimedia.org/wikipedia/commons/1/17/Shredded_pork_burrito.jpg"},{"name":"Feijoada","rarity":"legendary","id":"feijoada","subtitle":"Latin & Caribbean","details":"A slow-simmered Brazilian stew of black beans and pork, served with rice, greens, farofa and orange slices to cut the richness.","image":"https://upload.wikimedia.org/wikipedia/commons/9/90/Feijoada_%C3%A0_transmontada.jpg"},{"name":"Cuban Sandwich","rarity":"legendary","id":"cuban-sandwich","subtitle":"Latin & Caribbean","details":"Pressed Cuban bread layered with roast pork, ham, Swiss cheese, pickles and mustard, grilled until crisp and melting inside.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7b/Cuban_Sandwich_%283349116046%29.jpg"},{"name":"Peruvian Ceviche","rarity":"epic","id":"peruvian-ceviche","subtitle":"Latin & Caribbean","details":"Fresh raw fish cured in lime juice with red onion, chilli and coriander, served with sweet potato and corn, sharp and refreshing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Cebiche_de_corvina.JPG/1280px-Cebiche_de_corvina.JPG"},{"name":"Empanadas","rarity":"epic","id":"empanadas","subtitle":"Latin & Caribbean","details":"Pastry turnovers with folded or crimped edges, filled with seasoned meat, cheese or vegetables and baked or fried until golden.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Tapa_de_empanadillitas.JPG/1280px-Tapa_de_empanadillitas.JPG"},{"name":"Ropa Vieja","rarity":"epic","id":"ropa-vieja","subtitle":"Latin & Caribbean","details":"Beef slow-braised until it shreds into tender strands, simmered with tomatoes, peppers and onions, its name meaning old clothes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/RealRopaVieja.jpg/1280px-RealRopaVieja.jpg"},{"name":"Mole Poblano","rarity":"epic","id":"mole-poblano","subtitle":"Latin & Caribbean","details":"Chicken or turkey under a deep, complex sauce of chillies, spices and a little chocolate, a celebratory dish from Puebla, Mexico.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/ChickRedMole.JPG/1280px-ChickRedMole.JPG"},{"name":"Bandeja Paisa","rarity":"epic","id":"bandeja-paisa","subtitle":"Latin & Caribbean","details":"A generous Colombian platter of beans, rice, ground beef, chicharrón, fried egg, plantain, avocado and a small arepa.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Bandeja_paisa%2C_plato_Colombiano.jpg/1280px-Bandeja_paisa%2C_plato_Colombiano.jpg"},{"name":"Enchiladas","rarity":"rare","id":"enchiladas","subtitle":"Latin & Caribbean","details":"Corn tortillas rolled around chicken, cheese or beans, covered in chilli sauce and baked with more cheese until bubbling.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ec/Enchilada_Rice_Beans.jpg"},{"name":"Chiles Rellenos","rarity":"rare","id":"chiles-rellenos","subtitle":"Latin & Caribbean","details":"Roasted poblano chillies stuffed with cheese or seasoned meat, coated in fluffy egg batter and fried, then served in tomato sauce.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Chile_Rellenos.jpg/1280px-Chile_Rellenos.jpg"},{"name":"Pozole","rarity":"rare","id":"pozole","subtitle":"Latin & Caribbean","details":"A hearty Mexican soup of hominy and pork or chicken in a rich broth, finished at the table with radish, lettuce, onion and lime.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Green_pozole%2C_dressed_%2829161841908%29_%28cropped%29.jpg/1280px-Green_pozole%2C_dressed_%2829161841908%29_%28cropped%29.jpg"},{"name":"Tamales","rarity":"rare","id":"tamales","subtitle":"Latin & Caribbean","details":"Seasoned corn masa, often with a meat or chilli filling, wrapped in corn husks or banana leaves and steamed until tender.","image":"https://upload.wikimedia.org/wikipedia/commons/5/51/Tamal_oaxaque%C3%B1o.jpg"},{"name":"Arepas","rarity":"rare","id":"arepas","subtitle":"Latin & Caribbean","details":"Griddled or fried cornmeal cakes from Venezuela and Colombia, split and filled with cheese, meats, beans or avocado.","image":"https://upload.wikimedia.org/wikipedia/commons/d/dc/Arepitas_Food_Macro.jpg"},{"name":"Pabellón Criollo","rarity":"rare","id":"pabellon-criollo","subtitle":"Latin & Caribbean","details":"A Venezuelan plate of shredded beef, black beans, white rice and fried plantain, its colours said to mirror the national flag.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Pabell%C3%B3n_Criollo_Venezolano.jpg/1280px-Pabell%C3%B3n_Criollo_Venezolano.jpg"},{"name":"Mofongo","rarity":"rare","id":"mofongo","subtitle":"Latin & Caribbean","details":"Green plantains fried and mashed with garlic and pork cracklings, shaped into a mound and often served with a garlicky broth.","image":"https://upload.wikimedia.org/wikipedia/commons/4/41/Mofongo.jpg"},{"name":"Jerk Chicken","rarity":"rare","id":"jerk-chicken","subtitle":"Latin & Caribbean","details":"Chicken marinated in a fiery blend of Scotch bonnet chillies, allspice and thyme, then grilled until smoky and charred at the edges.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Jerk_Chicken_with_Jambalaya_and_Corn_Salad.jpg/1280px-Jerk_Chicken_with_Jambalaya_and_Corn_Salad.jpg"},{"name":"Tostadas","rarity":"uncommon","id":"tostadas","subtitle":"Latin & Caribbean","details":"Crisp flat tortillas piled with refried beans, shredded meat, lettuce, tomato, cheese and salsa, eaten with your hands, carefully.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Tostadas_Sencillas.jpg/1280px-Tostadas_Sencillas.jpg"},{"name":"Sopes","rarity":"uncommon","id":"sopes","subtitle":"Latin & Caribbean","details":"Thick little corn masa cakes with pinched rims, topped with beans, meat, lettuce, cheese and salsa for a satisfying bite.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Chicken_sope_at_La_Casa_Restaurant_-_December_2023_-_Sarah_Stierch_01.jpg/1280px-Chicken_sope_at_La_Casa_Restaurant_-_December_2023_-_Sarah_Stierch_01.jpg"},{"name":"Elote","rarity":"uncommon","id":"elote","subtitle":"Latin & Caribbean","details":"Grilled corn on the cob brushed with mayonnaise, dusted with cheese, chilli and lime, a beloved Mexican street snack.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Elote_asado_preparado.jpg/1280px-Elote_asado_preparado.jpg"},{"name":"Quesadilla","rarity":"uncommon","id":"quesadilla","subtitle":"Latin & Caribbean","details":"A folded tortilla griddled with melting cheese, sometimes with mushrooms, squash blossoms or meat tucked inside as well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Quesadilla%202.jpg?width=1024"},{"name":"Fajitas","rarity":"uncommon","id":"fajitas","subtitle":"Latin & Caribbean","details":"Sizzling strips of grilled meat with peppers and onions, brought to the table hot and wrapped in warm tortillas with salsa.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Chicken_fajita_platter%2C_Lone_Star_Texas_Grill%2C_Windsor%2C_Ontario%2C_2025-06-14_03.jpg/1280px-Chicken_fajita_platter%2C_Lone_Star_Texas_Grill%2C_Windsor%2C_Ontario%2C_2025-06-14_03.jpg"},{"name":"Carnitas","rarity":"uncommon","id":"carnitas","subtitle":"Latin & Caribbean","details":"Pork slow-cooked in its own fat until meltingly tender, then crisped at the edges, a Michoacán speciality served in tacos.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Carnitas.jpg/1280px-Carnitas.jpg"},{"name":"Birria Tacos","rarity":"uncommon","id":"birria-tacos","subtitle":"Latin & Caribbean","details":"Tortillas dipped in rich birria braising juices, filled with slow-cooked meat and cheese, griddled crisp and served with consommé.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Birria_tacos%2C_birria_consomme.jpg/1280px-Birria_tacos%2C_birria_consomme.jpg"},{"name":"Lechón Asado","rarity":"uncommon","id":"lechon-asado","subtitle":"Latin & Caribbean","details":"Pork marinated in sour orange, garlic and oregano, then slow-roasted until the meat is juicy and the skin turns deep golden.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Cochinillo_asado-Madrid.jpg/1280px-Cochinillo_asado-Madrid.jpg"},{"name":"Arroz con Pollo","rarity":"uncommon","id":"arroz-con-pollo","subtitle":"Latin & Caribbean","details":"Chicken simmered with seasoned rice, peppers, peas and saffron-toned spices in one pot, a comforting family dish across many regions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Arroz-con-Pollo.jpg/1280px-Arroz-con-Pollo.jpg"},{"name":"Pernil","rarity":"uncommon","id":"pernil","subtitle":"Latin & Caribbean","details":"Pork shoulder marinated with garlic and oregano and roasted low and slow until it falls apart, with crisp, well-seasoned skin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Pernil.1.jpg/1280px-Pernil.1.jpg"},{"name":"Doubles","rarity":"uncommon","id":"doubles","subtitle":"Latin & Caribbean","details":"Two soft fried flatbreads wrapped around curried chickpeas with chutneys and pepper sauce, a Trinidadian street breakfast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FOOD%20Doubles%202.jpg?width=800"},{"name":"Ackee and Saltfish","rarity":"uncommon","id":"ackee-and-saltfish","subtitle":"Latin & Caribbean","details":"Ackee fruit sautéed with salted cod, onions, peppers and tomatoes, a Jamaican favourite with a soft, buttery texture.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Ackee_and_Saltfish.jpg/1280px-Ackee_and_Saltfish.jpg"},{"name":"Rice and Peas","rarity":"common","id":"rice-and-peas","subtitle":"Latin & Caribbean","details":"Rice simmered in coconut milk with kidney beans or gungo peas and thyme, the classic Jamaican partner to jerk and curries.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Rice_and_Peas.jpg/1280px-Rice_and_Peas.jpg"},{"name":"Callaloo","rarity":"common","id":"callaloo","subtitle":"Latin & Caribbean","details":"Leafy greens simmered with coconut milk, okra, onions and peppers into a rich, earthy side or soup found across the Caribbean.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Callaloo.jpg/1280px-Callaloo.jpg"},{"name":"Griot","rarity":"common","id":"griot","subtitle":"Latin & Caribbean","details":"Haitian pork shoulder marinated in citrus and spices, braised then fried until crisp outside and tender within, served with pikliz.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Griot_ha%C3%AFtien_%2842675563925%29.jpg/1280px-Griot_ha%C3%AFtien_%2842675563925%29.jpg"},{"name":"Soup Joumou","rarity":"common","id":"soup-joumou","subtitle":"Latin & Caribbean","details":"A Haitian squash soup enriched with beef, vegetables and pasta, traditionally shared to celebrate independence and new beginnings.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Soup_joumou.jpg/1280px-Soup_joumou.jpg"},{"name":"Lomo Saltado","rarity":"common","id":"lomo-saltado","subtitle":"Latin & Caribbean","details":"Strips of beef stir-fried with onion, tomato and soy sauce, tossed with French fries and served over rice, a Peruvian favourite.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Lomo_Saltado_-_Lima%2C_Peru_Miraflores_%28Tiendecita_Blanca%29.jpg/1280px-Lomo_Saltado_-_Lima%2C_Peru_Miraflores_%28Tiendecita_Blanca%29.jpg"},{"name":"Anticuchos","rarity":"common","id":"anticuchos","subtitle":"Latin & Caribbean","details":"Skewers of marinated beef heart grilled over charcoal and brushed with a chilli and garlic sauce, a Peruvian street classic.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Anticuchos_-_Grilled_Beef_Heart_skewers.jpg/1280px-Anticuchos_-_Grilled_Beef_Heart_skewers.jpg"},{"name":"Papa a la Huancaína","rarity":"common","id":"papa-a-la-huancaina","subtitle":"Latin & Caribbean","details":"Sliced potatoes under a creamy, gently spicy cheese sauce made with ají amarillo chillies, served cold with egg and olives.","image":"https://upload.wikimedia.org/wikipedia/commons/7/74/Papa_a_la_huancaina.jpg"},{"name":"Ají de Gallina","rarity":"common","id":"aji-de-gallina","subtitle":"Latin & Caribbean","details":"Shredded chicken in a creamy walnut and ají amarillo sauce, thickened with bread and cheese and served over rice and potatoes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Aj%C3%AD_de_gallina.jpg/1280px-Aj%C3%AD_de_gallina.jpg"},{"name":"Picanha","rarity":"common","id":"picanha","subtitle":"Latin & Caribbean","details":"A prized Brazilian beef cut with a thick cap of fat, grilled on skewers and sliced so each piece carries crisp fat and juicy meat.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Picanha_%2814759358544%29.jpg/1280px-Picanha_%2814759358544%29.jpg"},{"name":"Moqueca","rarity":"common","id":"moqueca","subtitle":"Latin & Caribbean","details":"A Brazilian seafood stew simmered with tomatoes, peppers, onions, coconut milk and dendê oil, fragrant and gently rich.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Moqueca.jpg/1280px-Moqueca.jpg"},{"name":"Pastel de Choclo","rarity":"common","id":"pastel-de-choclo","subtitle":"Latin & Caribbean","details":"A Chilean corn-topped pie over seasoned ground beef, chicken, olives and egg, baked until the sweet corn crust turns golden.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Pastel_de_choclo.jpg/1280px-Pastel_de_choclo.jpg"},{"name":"Humitas","rarity":"common","id":"humitas","subtitle":"Latin & Caribbean","details":"Fresh corn blended with basil and cheese, wrapped in corn husks and steamed into soft, fragrant parcels from the Andes region.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Humitas_%28open%29.jpg/1280px-Humitas_%28open%29.jpg"},{"name":"Sancocho","rarity":"common","id":"sancocho","subtitle":"Latin & Caribbean","details":"A hearty Latin American stew of meats, plantain, yuca, corn and root vegetables simmered together in a seasoned broth.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Sancocho_de_espinazo_de_cerdo.jpg/1280px-Sancocho_de_espinazo_de_cerdo.jpg"},{"name":"Ajiaco","rarity":"common","id":"ajiaco","subtitle":"Latin & Caribbean","details":"A Colombian chicken and potato soup thickened by native potato varieties, served with corn, capers, avocado and cream.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d7/Ajiaco.jpg"},{"name":"Tostones","rarity":"common","id":"tostones","subtitle":"Latin & Caribbean","details":"Green plantain slices fried, flattened and fried again until crisp and golden, sprinkled with salt and often served with garlic sauce.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Tostones.JPG/1280px-Tostones.JPG"},{"name":"Maduros","rarity":"common","id":"maduros","subtitle":"Latin & Caribbean","details":"Ripe plantains fried until their edges caramelise deep amber, sweet and tender inside, a favourite side across the Caribbean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fried%20ripe%20plantain%20and%20beans%20stew.jpg?width=800"},{"name":"Falafel","rarity":"legendary","id":"falafel","subtitle":"Street Food & Snacks","details":"Ground chickpeas or fava beans seasoned with herbs and spices, shaped into balls or patties and fried until crisp and green-flecked.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Falafels_2.jpg/1280px-Falafels_2.jpg"},{"name":"Samosa","rarity":"legendary","id":"samosa","subtitle":"Street Food & Snacks","details":"Crisp pastry triangles filled with spiced potatoes, peas or minced meat, fried golden and served with tangy chutneys for dipping.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Samosas%2C_snack_food_at_Wikipedia%27s_16th_Birthday_celebration_in_Chittagong_%2801%29.jpg/1280px-Samosas%2C_snack_food_at_Wikipedia%27s_16th_Birthday_celebration_in_Chittagong_%2801%29.jpg"},{"name":"Poutine","rarity":"legendary","id":"poutine","subtitle":"Street Food & Snacks","details":"French fries covered in cheese curds and hot gravy, the curds softening into squeaky, melting pockets, a Canadian icon.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cc/Food_at_WIkimanian_2017_02.jpg"},{"name":"Doner Kebab","rarity":"legendary","id":"doner-kebab","subtitle":"Street Food & Snacks","details":"Seasoned meat cooked on a vertical rotisserie, shaved into warm flatbread with salad, sauces and sometimes a handful of fries.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/D%C3%B6ner_Kebab_auf_Teller.jpg/1280px-D%C3%B6ner_Kebab_auf_Teller.jpg"},{"name":"Bánh Mì","rarity":"epic","id":"banh-mi","subtitle":"Street Food & Snacks","details":"A crisp Vietnamese baguette filled with pickled vegetables, coriander, pâté or meats and chilli, balancing crunch, tang and heat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/B%C3%A1nh%20m%C3%AC.jpg?width=1024"},{"name":"Takoyaki","rarity":"epic","id":"takoyaki","subtitle":"Street Food & Snacks","details":"Batter balls cooked in a dimpled pan around pieces of octopus, brushed with sauce and topped with bonito flakes that wave in the heat.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d8/Takoyaki_by_yomi955.jpg"},{"name":"Gua Bao","rarity":"epic","id":"gua-bao","subtitle":"Street Food & Snacks","details":"A soft steamed bun folded around braised pork belly, pickled greens, crushed peanuts and coriander, rich, tangy and pillowy.","image":"https://upload.wikimedia.org/wikipedia/commons/0/08/Steamed_Sandwich%2Ctaken_by_LeoAlmighty.jpg"},{"name":"Soft Pretzel","rarity":"epic","id":"soft-pretzel","subtitle":"Street Food & Snacks","details":"A twisted, chewy bread with a deep mahogany crust from an alkaline bath, sprinkled with coarse salt and often served with mustard.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Gr%C3%BCndonnerstags-Brezel.jpg/1280px-Gr%C3%BCndonnerstags-Brezel.jpg"},{"name":"Korean Corn Dog","rarity":"epic","id":"korean-corn-dog","subtitle":"Street Food & Snacks","details":"A hot dog or cheese stick in a yeasty or rice-flour batter, sometimes rolled in potato cubes or crumbs, fried and dusted with sugar.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/CornDog.jpg/1280px-CornDog.jpg"},{"name":"Gyoza","rarity":"epic","id":"gyoza","subtitle":"Street Food & Snacks","details":"Japanese dumplings filled with seasoned pork and cabbage, pan-fried until their bottoms crisp, then steamed to finish tender.","image":"https://upload.wikimedia.org/wikipedia/commons/4/40/Gyoza_Houhi.jpg"},{"name":"Arancini","rarity":"rare","id":"arancini","subtitle":"Street Food & Snacks","details":"Sicilian rice balls, often filled with ragù, ham or cheese, crumbed and deep-fried until the shell is crisp and the centre creamy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Arancini_002.jpg/1280px-Arancini_002.jpg"},{"name":"Korokke","rarity":"rare","id":"korokke","subtitle":"Street Food & Snacks","details":"Japanese croquettes of mashed potato or béchamel mixed with meat or seafood, coated in panko crumbs and fried until crunchy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Potato_croquettes_001.jpg/1280px-Potato_croquettes_001.jpg"},{"name":"Pirozhki","rarity":"rare","id":"pirozhki","subtitle":"Street Food & Snacks","details":"Soft baked or fried buns filled with cabbage, potato, meat or mushrooms, a handheld snack found across Russia and Eastern Europe.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Piroshki.JPG/1280px-Piroshki.JPG"},{"name":"Taiyaki","rarity":"rare","id":"taiyaki","subtitle":"Street Food & Snacks","details":"Japanese fish-shaped cakes baked in a mould, traditionally filled with sweet red bean paste, crisp at the edges and soft inside.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Taiyaki_003.jpg/1280px-Taiyaki_003.jpg"},{"name":"Tanghulu","rarity":"rare","id":"tanghulu","subtitle":"Street Food & Snacks","details":"Skewers of fresh fruit, often strawberries or hawthorn berries, dipped in clear sugar syrup that hardens into a glassy, crunchy shell.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Tanghulu_sold_in_Shilin_Night_Market.jpg/1280px-Tanghulu_sold_in_Shilin_Night_Market.jpg"},{"name":"Halloumi Fries","rarity":"rare","id":"halloumi-fries","subtitle":"Street Food & Snacks","details":"Thick batons of firm Cypriot halloumi, coated and fried until crisp and golden outside while staying soft and salty within, served hot with a dip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HALLOUMI%20FRIES%20%28small%29%201%20-%20Jonny%27s%202025-05-27.jpg?width=1024"},{"name":"Mozzarella Sticks","rarity":"rare","id":"mozzarella-sticks","subtitle":"Street Food & Snacks","details":"Breaded sticks of mozzarella fried to a crisp, crunchy shell, made for the moment the molten cheese pulls into a long, stretchy strand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fried%20Mozzarella%20Sticks%20at%20Millers%20Pub%20%28301456962%29.jpg?width=1024"},{"name":"Jalapeño Poppers","rarity":"rare","id":"jalapeno-poppers","subtitle":"Street Food & Snacks","details":"Jalapeño halves filled with soft cheese, crumbed and fried until crisp, delivering creamy richness first and a lively chilli warmth after.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jalape%C3%B1os%20poppers%20con%20queso.jpg?width=1024"},{"name":"Loaded Nachos","rarity":"rare","id":"loaded-nachos","subtitle":"Street Food & Snacks","details":"A sharing plate of crisp tortilla chips layered with melted cheese, beans, salsa, jalapeños and cool toppings, built for digging in together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nachos%20with%20sour%20cream%2C%20salsa%20and%20guacamole.jpg?width=1024"},{"name":"Bunny Chow","rarity":"uncommon","id":"bunny-chow","subtitle":"Street Food & Snacks","details":"A hollowed loaf of white bread filled to the brim with curry, a hands-on Durban street classic eaten by tearing off pieces of the bread itself.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bunny%20Chow%20Close%20Up.JPG?width=1024"},{"name":"Poke Bowl","rarity":"uncommon","id":"poke-bowl","subtitle":"Street Food & Snacks","details":"Cubes of raw fish, often tuna or salmon, seasoned and served over warm rice with vegetables, sauces and crunchy toppings in a colourful bowl.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Poke%20Bowl%20in%20Loviisa.jpg?width=1024"},{"name":"Okonomiyaki","rarity":"uncommon","id":"okonomiyaki","subtitle":"Street Food & Snacks","details":"A savoury Japanese pancake of batter and shredded cabbage griddled with fillings, brushed with sweet sauce, mayonnaise and bonito flakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Okonomiyaki%20-a%20Japanese%20savory%20pancake%20in%20Osaka%2C%20Japan.jpg?width=1024"},{"name":"Currywurst","rarity":"uncommon","id":"currywurst","subtitle":"Street Food & Snacks","details":"Sliced German sausage under a warm curry-spiced ketchup sauce, usually served with fries, a beloved Berlin snack-bar pairing of spice and tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Currywurst%20hamburg.jpg?width=1024"},{"name":"Bratwurst in a Bun","rarity":"uncommon","id":"bratwurst-in-a-bun","subtitle":"Street Food & Snacks","details":"A juicy grilled bratwurst tucked into a crusty roll with mustard, simple street fare where the spiced, snappy sausage does all the talking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rostbratwurstbrot.png?width=480"},{"name":"Scallion Pancakes","rarity":"uncommon","id":"scallion-pancakes","subtitle":"Street Food & Snacks","details":"Flaky, layered flatbreads rolled with oil and chopped scallions, pan-fried until crisp at the edges and chewy inside, cut into wedges for sharing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plate%20of%20scallion%20pancakes.jpg?width=1024"},{"name":"Pigs in Blankets","rarity":"uncommon","id":"pigs-in-blankets","subtitle":"Street Food & Snacks","details":"Small sausages wrapped in streaky bacon and roasted until the bacon crisps, a bite-sized favourite long associated with festive roast dinners.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pigs%20in%20blankets%202.jpg?width=1024"},{"name":"Potato Wedges","rarity":"uncommon","id":"potato-wedges","subtitle":"Street Food & Snacks","details":"Thick, skin-on wedges of potato, seasoned and baked or fried until crisp outside and fluffy within, made for dipping and sharing as a side.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roasted%20Potato%20Wedges%20with%20Shallots%20and%20Rosemary%20%285706897999%29.jpg?width=1024"},{"name":"Loaded Fries","rarity":"uncommon","id":"loaded-fries","subtitle":"Street Food & Snacks","details":"A generous heap of hot fries buried under melted cheese, sauces and savoury toppings, turning a simple side into a full sharing plate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LoadedCheeseFries%20C2Cafe%20Mumbai.jpg?width=1024"},{"name":"Fried Cheese Curds","rarity":"uncommon","id":"fried-cheese-curds","subtitle":"Street Food & Snacks","details":"Fresh cheese curds in a light batter, fried until crisp outside and just melted within, a squeaky Midwest fairground and tavern favourite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Deep%20fried%20cheese%20curds%20.jpg?width=1024"},{"name":"Onion Rings","rarity":"uncommon","id":"onion-rings","subtitle":"Street Food & Snacks","details":"Thick slices of sweet onion dipped in batter or crumbs and fried into crisp golden rings, tender inside and made for ketchup or a creamy dip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Onion%20rings%20served%20in%20Fort%20William.jpg?width=1024"},{"name":"Fried Pickles","rarity":"uncommon","id":"fried-pickles","subtitle":"Street Food & Snacks","details":"Tangy pickle slices or spears in seasoned batter, fried until crisp, giving a hot, crunchy bite with a sharp, briny snap in the middle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fried%20dill%20pickles.jpg?width=1024"},{"name":"Garlic Knots","rarity":"uncommon","id":"garlic-knots","subtitle":"Street Food & Snacks","details":"Small knots of pizza dough baked golden, then slicked with garlic butter and herbs, soft and chewy inside and made for dunking in marinara.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2021-09-11%2016%2032%2001%20Garlic%20knots%20in%20the%20Dulles%20section%20of%20Sterling%2C%20Loudoun%20County%2C%20Virginia.jpg?width=1024"},{"name":"Bruschetta","rarity":"uncommon","id":"bruschetta","subtitle":"Street Food & Snacks","details":"Grilled bread rubbed with garlic and topped with chopped tomatoes, basil and olive oil, a simple Italian starter built on ripe, fresh flavour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bruschetta%20at%20The%20Bar%20at%20MacArthur%20Place%20-%20Sarah%20Stierch.jpg?width=1024"},{"name":"Chili Cheese Dog","rarity":"uncommon","id":"chili-cheese-dog","subtitle":"Street Food & Snacks","details":"A hot dog buried under beef chili, shredded cheddar and diced onion — the messy, fork-optional ballpark and drive-in classic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chili%20dog%20with%20fries.jpg?width=1024"},{"name":"Tornado Potato","rarity":"common","id":"tornado-potato","subtitle":"Street Food & Snacks","details":"A whole potato cut into a long spiral on a skewer, stretched, fried crisp and dusted with seasoning, a swirling Korean street-market snack.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Hoeori-gamja_1.jpg/1280px-Hoeori-gamja_1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Panipuri","rarity":"common","id":"panipuri","subtitle":"Street Food & Snacks","details":"Crisp hollow puris filled with spiced potato and tangy, minty water, eaten in one bite so the shell shatters and the flavours flood together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indian%20cuisine-Panipuri-03.jpg?width=1024"},{"name":"Popcorn","rarity":"common","id":"popcorn","subtitle":"Street Food & Snacks","details":"Kernels heated until they burst into light, fluffy puffs, tossed with salt or butter — a simple, crunchy snack made for films and fairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Popcorn%209.jpg?width=1024"},{"name":"Potato Chips and Dip","rarity":"common","id":"potato-chips-and-dip","subtitle":"Street Food & Snacks","details":"Crisp, thin potato chips served with a cool, creamy dip for dunking, the dependable centrepiece of snack tables and casual gatherings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kiwi%20Dip.jpg?width=1024"},{"name":"Tortilla Chips and Guacamole","rarity":"common","id":"tortilla-chips-and-guacamole","subtitle":"Street Food & Snacks","details":"Crisp tortilla chips beside guacamole of mashed avocado, lime, onion and coriander, a fresh, creamy and crunchy pairing made for scooping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guacamole%20and%20chips%20-%20Stierch.jpg?width=1024"},{"name":"Pretzel Bites","rarity":"common","id":"pretzel-bites","subtitle":"Street Food & Snacks","details":"Soft pretzel dough cut into bite-sized pieces, boiled, salted and baked deep golden, chewy inside and often served with warm cheese sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Culver%27s%20Pretzel%20Bites.jpg?width=1024"},{"name":"Roasted Chestnuts","rarity":"common","id":"roasted-chestnuts","subtitle":"Street Food & Snacks","details":"Chestnuts scored and roasted until their shells split and the nuts inside turn tender, sweet and smoky, a classic cold-weather street treat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caldarroste.jpg?width=1024"},{"name":"Candied Nuts","rarity":"common","id":"candied-nuts","subtitle":"Street Food & Snacks","details":"Almonds, pecans or peanuts cooked in spiced sugar until they wear a crisp, glossy shell, sweet and crunchy by the handful at markets and fairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gebrannte%20Mandeln.JPG?width=1024"},{"name":"Esquites","rarity":"common","id":"esquites","subtitle":"Street Food & Snacks","details":"Warm Mexican corn kernels served in a cup with mayonnaise, cheese, lime and chilli, a spoonable street snack that is creamy, tangy and spicy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Esquites%20in%20the%20streets%20of%20Coyoacan%2C%20Mexico.jpg?width=1024"},{"name":"Onigiri","rarity":"common","id":"onigiri","subtitle":"Street Food & Snacks","details":"Japanese rice moulded into triangles around a savoury filling and partly wrapped in nori, a portable, everyday snack of gentle, clean flavours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Three-onigiris.jpg?width=1024"},{"name":"Rice Krispie Treat","rarity":"common","id":"rice-krispie-treat","subtitle":"Street Food & Snacks","details":"Puffed rice cereal folded through melted marshmallow and butter, pressed into a slab and cut into chewy, sticky squares of simple sweetness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RKTsquares.jpg?width=1024"},{"name":"Chocolate-Covered Pretzels","rarity":"common","id":"chocolate-covered-pretzels","subtitle":"Street Food & Snacks","details":"Crisp salted pretzels dipped in smooth chocolate and left to set, giving a sweet-and-salty crunch that makes them hard to stop eating.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vegan%20Chocolate%20Covered%20Pretzels%20%284216679799%29.jpg?width=1024"},{"name":"Caramel Corn","rarity":"common","id":"caramel-corn","subtitle":"Street Food & Snacks","details":"Popcorn tumbled in a buttery caramel coating and baked until crisp and glossy, a sweet, crunchy treat long sold at fairs and ball games.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caramel%20Popcorn%20%2832402585090%29.jpg?width=1024"},{"name":"Kettle Corn","rarity":"common","id":"kettle-corn","subtitle":"Street Food & Snacks","details":"Popcorn cooked in a large kettle with oil, sugar and salt, so every puff carries a delicate sweet-and-salty glaze and a light crunch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Organic%20homemade%20kettle%20corn%20recipe%20%284253371172%29.jpg?width=1024"},{"name":"Cotton Candy","rarity":"common","id":"cotton-candy","subtitle":"Street Food & Snacks","details":"Sugar spun into airy, pastel strands and gathered onto a stick or cone, melting on the tongue in an instant of pure fairground sweetness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pink%20Cotton%20Candy.jpg?width=1024"},{"name":"Snow Cone","rarity":"common","id":"snow-cone","subtitle":"Street Food & Snacks","details":"Finely shaved ice mounded in a cup or cone and drenched in bright, fruity syrup, an icy treat made for hot days, fairs and boardwalks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shavedice.jpg?width=1024"},{"name":"Soft Serve Ice Cream Cone","rarity":"common","id":"soft-serve-ice-cream-cone","subtitle":"Street Food & Snacks","details":"Smooth ice cream swirled in soft peaks into a crisp cone, light and creamy, and best eaten quickly before the tall curl begins to melt.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Liat%20Portal%20for%20Foodie%20Disorder%20-%20Chocolate%20and%20vanilla%20soft%20serve%20ice%20cream%20cone.jpg?width=1024"},{"name":"Churro Bites","rarity":"common","id":"churro-bites","subtitle":"Street Food & Snacks","details":"Short pieces of ridged fried dough rolled in cinnamon sugar, crisp outside and soft within, sized for snacking and dunking in chocolate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Small%20Churros%2C%20San%20Churro%20Carousel%2C%202026%20%2801%29.jpg?width=1024"},{"name":"Fried Dough","rarity":"common","id":"fried-dough","subtitle":"Street Food & Snacks","details":"Batter and dough fried until crisp and golden, then dusted with sugar or given sweet toppings, a fairground staple eaten warm from the fryer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Funnel%20cake%2020040821%20172200%201.1655x1275.jpg?width=1024"},{"name":"Beignets","rarity":"common","id":"beignets","subtitle":"Street Food & Snacks","details":"Pillowy squares of yeast dough, fried until puffed and buried under powdered sugar, a New Orleans café classic served warm with coffee.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beignets%20served%20at%20Caf%C3%A9%20du%20Monde%2C%20New%20Orleans%2C%20April%202014.jpg?width=1024"},{"name":"Loukoumades","rarity":"common","id":"loukoumades","subtitle":"Street Food & Snacks","details":"Small Greek dough puffs fried crisp, then soaked in honey syrup and dusted with cinnamon or nuts, eaten warm while the centres stay soft.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Loukoumades.jpg?width=1024"},{"name":"Tiramisu","rarity":"chase","id":"tiramisu","subtitle":"Desserts & Baking","details":"Layers of coffee-soaked ladyfingers and smooth mascarpone cream, dusted with cocoa — a chilled Italian dessert of gentle bitterness and silk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tiramisu%20slice%20with%20cocoa%20powder%2C%20May%202009.jpg?width=1024"},{"name":"Crème Brûlée","rarity":"legendary","id":"creme-brulee","subtitle":"Desserts & Baking","details":"Silky baked vanilla custard under a thin shell of caramelised sugar, cracked with a spoon to reach the cool, creamy centre beneath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cr%C3%A8me%20br%C3%BBl%C3%A9e%20in%20an%20aluminum%20foil%20cup.jpg?width=1024"},{"name":"New York Cheesecake","rarity":"legendary","id":"new-york-cheesecake","subtitle":"Desserts & Baking","details":"A dense, rich cheesecake on a crumb base, baked smooth and served plain or with fruit, prized for its creamy weight and gentle tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New%20York%20cheesecake%202.jpg?width=1024"},{"name":"Chocolate Soufflé","rarity":"legendary","id":"chocolate-souffle","subtitle":"Desserts & Baking","details":"A light, risen baked dessert of egg whites and dark chocolate, served straight from the oven before its airy centre begins to settle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chocolate%20souffle1.JPG?width=1024"},{"name":"Black Forest Cake","rarity":"epic","id":"black-forest-cake","subtitle":"Desserts & Baking","details":"Layers of chocolate sponge, whipped cream and cherries, often with chocolate shavings, a German cake balancing richness and sharp fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20Forest%20cake%205.jpg?width=1024"},{"name":"Baklava","rarity":"epic","id":"baklava","subtitle":"Desserts & Baking","details":"Dozens of crisp filo layers with chopped nuts and honey or syrup, cut into diamonds — sticky, flaky and rich in small, satisfying pieces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turkish%20Baklava.JPG?width=1024"},{"name":"French Macarons","rarity":"epic","id":"french-macarons","subtitle":"Desserts & Baking","details":"Delicate almond meringue shells with a smooth filling, crisp outside and chewy within, made in many colours and flavours in neat pairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close-up%20of%20vibrant%20and%20colorful%20macarons%20displayed%20in%20rows%2C%20highlighting%20texture%20and%20detail.jpg?width=1024"},{"name":"Apple Pie","rarity":"epic","id":"apple-pie","subtitle":"Desserts & Baking","details":"Spiced apples baked under a golden pastry crust, sometimes latticed, served warm or cold — a homely pie of tender fruit and crisp pastry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Slice%20of%20apple%20pie%202.jpg?width=1024"},{"name":"Key Lime Pie","rarity":"epic","id":"key-lime-pie","subtitle":"Desserts & Baking","details":"A tangy custard of key lime juice in a crumb crust, topped with cream or meringue, named for the small limes associated with the Florida Keys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Slice%20of%20key%20lime%20pie%20by%20Marc%20Averette.jpg?width=1024"},{"name":"Banoffee Pie","rarity":"epic","id":"banoffee-pie","subtitle":"Desserts & Baking","details":"A crumb base layered with caramel toffee, sliced bananas and whipped cream, its name blending banana and toffee into one rich, soft pie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banoffeepie.jpg?width=1024"},{"name":"Italian Gelato","rarity":"epic","id":"italian-gelato","subtitle":"Desserts & Baking","details":"Dense, slowly churned Italian ice cream served a little warmer than usual, giving intense flavour and a silky texture in every scoop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stracciatella%20gelato.jpg?width=1024"},{"name":"Chocolate Lava Cake","rarity":"rare","id":"chocolate-lava-cake","subtitle":"Desserts & Baking","details":"An individual chocolate cake baked so its centre stays liquid, flowing out like lava when cut, usually served warm with cream or ice cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vegan%20Flourless%20Swiss%20Chocolate%20Molten%20Lava%20Cake%20%284865230786%29.jpg?width=1024"},{"name":"Panna Cotta","rarity":"rare","id":"panna-cotta","subtitle":"Desserts & Baking","details":"An Italian dessert of cream gently set with gelatine, served chilled with berries or sauce, trembling softly and tasting of sweet cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panna%20Cotta%20with%20fresh%20berries%20%28detail%29.jpg?width=1024"},{"name":"Pavlova","rarity":"rare","id":"pavlova","subtitle":"Desserts & Baking","details":"A crisp meringue shell with a marshmallow-soft centre, crowned with whipped cream and fresh fruit, a light dessert of contrast and colour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pavlova%20cake%20-%20Down%20under%20dessert.jpg?width=1024"},{"name":"Sticky Toffee Pudding","rarity":"rare","id":"sticky-toffee-pudding","subtitle":"Desserts & Baking","details":"A moist date sponge under a warm toffee sauce, served with cream, custard or ice cream — a dark, comforting British pudding of deep sweetness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sticky%20toffee%20pudding%2C%20rum%20butterscotch%20sauce%20and%20vanilla%20ice%20cream%20%28v%29%20-%20Post%20House%20Cafe%2C%20Brighton%202024-01-28.jpg?width=1024"},{"name":"Bread and Butter Pudding","rarity":"rare","id":"bread-and-butter-pudding","subtitle":"Desserts & Baking","details":"Slices of buttered bread baked in sweet custard, often with dried fruit, emerging golden and soft, a thrifty classic of the British kitchen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bread%20and%20butter%20pudding%20hotel%20dish.jpg?width=1024"},{"name":"Rice Pudding","rarity":"rare","id":"rice-pudding","subtitle":"Desserts & Baking","details":"Rice simmered slowly in milk until thick and creamy, sweetened and often spiced with cinnamon or nutmeg, served warm or chilled in a bowl.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Risengroed.jpg?width=1024"},{"name":"Crème Caramel","rarity":"rare","id":"creme-caramel","subtitle":"Desserts & Baking","details":"A smooth baked custard under a layer of soft caramel, turned out so the amber sauce pools over the top, gentle and silky in every spoonful.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Italian%20Creme%20Caramel.JPG?width=1024"},{"name":"Churros with Chocolate","rarity":"rare","id":"churros-with-chocolate","subtitle":"Desserts & Baking","details":"Long ridged sticks of fried dough dusted with cinnamon sugar, served with a cup of thick, dark hot chocolate made for dunking each bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Churros%20with%20dark%20chocolate%20dip.jpg?width=1024"},{"name":"Cinnamon Rolls","rarity":"rare","id":"cinnamon-rolls","subtitle":"Desserts & Baking","details":"Soft spirals of yeasted dough rolled with cinnamon sugar and baked, then glazed while warm so the sweet filling turns sticky and fragrant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cinnamon%20rolls%20glazed%2C%20July%202009.jpg?width=1024"},{"name":"Banana Bread","rarity":"rare","id":"banana-bread","subtitle":"Desserts & Baking","details":"A moist, tender loaf made with ripe bananas, sliced thick for breakfast or tea, its sweetness and aroma deepening as the bananas darken.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Loaf%20of%20banana%20date%20bread%20with%20a%20slice%20cut%20off.jpg?width=1024"},{"name":"Carrot Cake","rarity":"rare","id":"carrot-cake","subtitle":"Desserts & Baking","details":"A spiced sponge studded with grated carrot and often nuts, layered with cream cheese frosting — moist, warmly spiced and generously iced.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carrot%20cake%20-%20Milfey%20Patisserie%202026-04-04.jpg?width=1024"},{"name":"Red Velvet Cake","rarity":"uncommon","id":"red-velvet-cake","subtitle":"Desserts & Baking","details":"A softly cocoa-flavoured cake with a deep red crumb, layered with cream cheese frosting, known as much for its colour as its tender bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red%20velvet%20cake%20slice.jpg?width=1024"},{"name":"German Chocolate Cake","rarity":"uncommon","id":"german-chocolate-cake","subtitle":"Desserts & Baking","details":"Layers of mild chocolate cake with a coconut and pecan filling, a rich American cake whose name honours a chocolatier rather than a country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/German%20Chocolate%20Cake%2C%20April%202008.jpg?width=1024"},{"name":"Angel Food Cake","rarity":"uncommon","id":"angel-food-cake","subtitle":"Desserts & Baking","details":"A feather-light sponge made with whipped egg whites and no butter, baked tall and served with berries or cream for its airy, delicate crumb.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Angel%20food%20cake%20texture.jpg?width=1024"},{"name":"Pound Cake","rarity":"uncommon","id":"pound-cake","subtitle":"Desserts & Baking","details":"A firm, buttery loaf traditionally made from a pound each of flour, butter, eggs and sugar, sliced plain or served with fruit and cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pound%20cake%203.jpg?width=1024"},{"name":"Lemon Drizzle Cake","rarity":"uncommon","id":"lemon-drizzle-cake","subtitle":"Desserts & Baking","details":"A light lemon sponge soaked while warm with sharp lemon syrup, giving a moist crumb and a crisp, tangy-sweet top in every slice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coffee%20lemon%20drizzle%20cake%20Gibberd%20Garden%20Harlow%20Essex%20England%2003%20darker.jpg?width=1024"},{"name":"Victoria Sponge","rarity":"uncommon","id":"victoria-sponge","subtitle":"Desserts & Baking","details":"Two light sponge layers sandwiched with jam and cream or buttercream, a classic British tea cake named in honour of Queen Victoria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Victoria%20Sponge%20Cake.jpg?width=1024"},{"name":"Fruitcake","rarity":"uncommon","id":"fruitcake","subtitle":"Desserts & Baking","details":"A dense cake packed with dried and candied fruit and nuts, often spiced and matured for weeks, sliced thin for festive tables and teas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fruitcake.jpg?width=1024"},{"name":"Brownies","rarity":"uncommon","id":"brownies","subtitle":"Desserts & Baking","details":"Dense, fudgy squares of chocolate cake with a crackly top, sometimes studded with nuts, sitting between cake and fudge in every rich bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chocolate%20brownies%20without%20table.jpg?width=1024"},{"name":"Chocolate Chip Cookies","rarity":"uncommon","id":"chocolate-chip-cookies","subtitle":"Desserts & Baking","details":"Buttery drop cookies studded with chocolate chips, baked until the edges crisp and the centers stay soft, chewy, and warmly sweet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/6cookies.JPG?width=1024"},{"name":"Snickerdoodles","rarity":"uncommon","id":"snickerdoodles","subtitle":"Desserts & Baking","details":"Soft sugar cookies rolled in cinnamon sugar before baking, with a lightly tangy crumb and a crackled, warmly spiced golden top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/12-18-2017_Snickerdoodles_%2810_of_25%29.jpg?width=1024"},{"name":"Blueberry Muffins","rarity":"uncommon","id":"blueberry-muffins","subtitle":"Desserts & Baking","details":"Tender golden muffins bursting with juicy blueberries under a domed, lightly crisp top, equally at home at breakfast or snack time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blueberry_muffins%2C_whole_and_partial.jpg?width=1024"},{"name":"Pain au Chocolat","rarity":"uncommon","id":"pain-au-chocolat","subtitle":"Desserts & Baking","details":"Flaky laminated pastry wrapped around batons of dark chocolate, baked until the layers puff, shatter, and turn deep golden brown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pain_au_chocolat_Luc_Viatour.jpg?width=1024"},{"name":"Éclair","rarity":"uncommon","id":"eclair","subtitle":"Desserts & Baking","details":"A crisp choux pastry finger filled with smooth pastry cream and finished with a glossy chocolate glaze on top, eaten chilled.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eclair_au_cafe_make_hk.jpg?width=1024"},{"name":"Profiteroles","rarity":"uncommon","id":"profiteroles","subtitle":"Desserts & Baking","details":"Small choux pastry puffs filled with cream or ice cream and draped in warm chocolate sauce, often served stacked in a small pile.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Profiteroles_with_chocolate_sauce%2C_February_2010.jpg?width=1024"},{"name":"Mille-Feuille","rarity":"uncommon","id":"mille-feuille","subtitle":"Desserts & Baking","details":"Crisp puff pastry layered with pastry cream and topped with patterned icing, its name meaning a thousand leaves for its many layers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Millefoglie_from_the_Cossetta_patisserie.jpg?width=1024"},{"name":"Lemon Tart","rarity":"uncommon","id":"lemon-tart","subtitle":"Desserts & Baking","details":"A crisp pastry shell filled with bright, silky lemon curd, balancing sharp citrus tang against buttery sweetness in every slice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_Lemon_Meringue_Tart.jpg?width=1024"},{"name":"Bakewell Tart","rarity":"uncommon","id":"bakewell-tart","subtitle":"Desserts & Baking","details":"An English tart of shortcrust pastry layered with jam and almond frangipane, often finished with icing and a single cherry on top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bakewell_tart_on_a_plate.jpg?width=1024"},{"name":"Cupcakes","rarity":"common","id":"cupcakes","subtitle":"Desserts & Baking","details":"Small individual sponge cakes baked in paper cases and crowned with swirls of frosting, sprinkles, or other sweet decorations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Birthday_Cupcakes.jpg?width=1024"},{"name":"Glazed Donuts","rarity":"common","id":"glazed-donuts","subtitle":"Desserts & Baking","details":"Soft yeast-raised rings, fried until pillowy and dipped in a thin sugar glaze that sets into a delicate, crackly sweet shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Glazed_doughnut_%281387303%29.jpg?width=1024"},{"name":"Jelly Donuts","rarity":"common","id":"jelly-donuts","subtitle":"Desserts & Baking","details":"Pillowy fried doughnuts rolled in sugar and filled with fruit jelly, so each bite gives a burst of jam from the soft center.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-03-01_10_21_50_A_sugar-coated_raspberry_jelly_doughnut_which_has_been_broken_open_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Danish Pastry","rarity":"common","id":"danish-pastry","subtitle":"Desserts & Baking","details":"Laminated yeast pastry folded around sweet fillings such as custard, fruit, or almond paste, baked glossy, flaky, and golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Glazed_apple_Danish.jpg?width=1024"},{"name":"Apple Strudel","rarity":"common","id":"apple-strudel","subtitle":"Desserts & Baking","details":"Paper-thin pastry rolled around spiced apples, breadcrumbs, and raisins, baked until crisp and dusted with powdered sugar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Austrian_Apple_Strudel_%283321759680%29.jpg?width=1024"},{"name":"Stollen","rarity":"common","id":"stollen","subtitle":"Desserts & Baking","details":"A dense German Christmas bread studded with dried fruit, candied peel, and marzipan, coated thickly in powdered sugar after baking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stollen-Dresdner_Christstollen.jpg?width=1024"},{"name":"Panettone","rarity":"common","id":"panettone","subtitle":"Desserts & Baking","details":"A tall, domed Italian Christmas bread with a soft, airy crumb, scented with citrus and studded with candied fruit and raisins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Home_made_panettone_by_Nicola_%285300955223%29.jpg?width=1024"},{"name":"Babka","rarity":"common","id":"babka","subtitle":"Desserts & Baking","details":"A rich braided yeast cake swirled with chocolate or cinnamon filling, sliced to reveal its distinctive marbled spiral pattern.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chocolate_babka.jpg?width=1024"},{"name":"Rugelach","rarity":"common","id":"rugelach","subtitle":"Desserts & Baking","details":"Small crescent pastries rolled around fillings of jam, nuts, chocolate, or cinnamon sugar, with a tender, flaky cream-cheese dough.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blackberry_Rugelach_%28cropped%29.jpg?width=1024"},{"name":"Hamantaschen","rarity":"common","id":"hamantaschen","subtitle":"Desserts & Baking","details":"Triangular filled cookies folded around poppy seed, prune, or jam centers, their three-cornered shape pinched firmly at the edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hamantaschen%2C_strawberry.jpg?width=1024"},{"name":"Mooncakes","rarity":"common","id":"mooncakes","subtitle":"Desserts & Baking","details":"Round baked pastries with patterned crusts and rich fillings such as lotus seed paste or salted egg yolk, shared in small slices.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fresh_meat_mooncakes.jpg?width=1024"},{"name":"Daifuku Mochi","rarity":"common","id":"daifuku-mochi","subtitle":"Desserts & Baking","details":"Soft, chewy Japanese rice cakes wrapped around sweet fillings, classically red bean paste, sometimes with a whole strawberry inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Daifuku.JPG?width=1024"},{"name":"Gulab Jamun","rarity":"common","id":"gulab-jamun","subtitle":"Desserts & Baking","details":"Soft milk-solid dumplings fried golden and soaked in rose or cardamom syrup, served warm and glossy across South Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bowl_of_Gulab_Jamuns.jpg?width=1024"},{"name":"Rasmalai","rarity":"common","id":"rasmalai","subtitle":"Desserts & Baking","details":"Feather-light cheese discs soaked in chilled, saffron and cardamom scented milk, garnished with pistachios and served cold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ras_Malai.JPG?width=1024"},{"name":"Jalebi","rarity":"common","id":"jalebi","subtitle":"Desserts & Baking","details":"Crisp spirals of fermented batter fried and soaked in saffron syrup, eaten hot so the shell stays crunchy and sticky-sweet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hot_Jalebi-MA10.jpg?width=1024"},{"name":"Kulfi","rarity":"common","id":"kulfi","subtitle":"Desserts & Baking","details":"A dense Indian frozen dessert made by slowly reducing milk with cardamom, saffron, or pistachio, set in molds and served sliced.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kulfi_2.jpg?width=1024"},{"name":"Halo-Halo","rarity":"common","id":"halo-halo","subtitle":"Desserts & Baking","details":"A Filipino shaved ice dessert layered with sweet beans, jellies, fruits, evaporated milk, and often a scoop of purple yam ice cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Halo-Halo_or_mix_mix.jpg?width=1024"},{"name":"Bingsu","rarity":"common","id":"bingsu","subtitle":"Desserts & Baking","details":"Korean shaved ice piled high and milky-soft, topped with sweet red beans, fruit, rice cakes, or cheesecake cubes and condensed milk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bingsu_2.jpg?width=1024"},{"name":"Kakigori","rarity":"common","id":"kakigori","subtitle":"Desserts & Baking","details":"Japanese shaved ice heaped into a fluffy mound and drenched in flavored syrups such as matcha, strawberry, or sweet melon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macha_kakigori_snow_cone.jpg?width=1024"},{"name":"Ice Cream Sundae","rarity":"common","id":"ice-cream-sundae","subtitle":"Desserts & Baking","details":"Scoops of ice cream layered in a tall glass with sauce, whipped cream, nuts, and a cherry, built for eating with a long spoon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ice_Cream_Sundae_%285083018504%29.jpg?width=1024"},{"name":"Banana Split","rarity":"common","id":"banana-split","subtitle":"Desserts & Baking","details":"A split banana cradling scoops of ice cream with chocolate, strawberry, and pineapple sauces, whipped cream, nuts, and cherries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E2%80%9CAll_American%E2%80%9D_Banana_Split.jpg?width=1024"},{"name":"Sorbet","rarity":"common","id":"sorbet","subtitle":"Desserts & Baking","details":"A smooth frozen dessert churned from fruit puree and sugar without dairy, intensely flavored and refreshing between courses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bowl_of_watermelon_lime_sorbet_%284803357504%29.jpg?width=1024"},{"name":"Granita","rarity":"common","id":"granita","subtitle":"Desserts & Baking","details":"A Sicilian frozen dessert of sweetened fruit or coffee ice, scraped into coarse, sparkling crystals and spooned into a glass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Granita_Sicilian_15-8-2024.jpg?width=1024"},{"name":"Ice Lolly","rarity":"common","id":"ice-lolly","subtitle":"Desserts & Baking","details":"Fruit juice, puree, or flavored water frozen solid around a stick, eaten by hand as it melts into a sweet, icy treat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cherry_Popsicle_%2820913582635%29.jpg?width=1024"},{"name":"Frozen Yogurt","rarity":"common","id":"frozen-yogurt","subtitle":"Desserts & Baking","details":"A tangy frozen dessert churned from yogurt, served soft in swirls and often topped with fresh fruit, granola, or candy pieces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cup_of_Frozen_Yogurt_%2815840156083%29.jpg?width=1024"},{"name":"English Trifle","rarity":"common","id":"english-trifle","subtitle":"Desserts & Baking","details":"Layers of sponge, custard, jelly, fruit, and whipped cream built in a glass bowl so every spoonful carries a little of each layer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trifle_4layer.jpg?width=1024"},{"name":"Butter Croissant","rarity":"chase","id":"butter-croissant","subtitle":"Breakfast & Brunch","details":"A crescent of laminated dough layered with butter, baked to a deep golden crisp outside with a soft, honeycombed crumb within.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Croissants_au_beurre_%2818953292873%29.jpg?width=1024"},{"name":"Eggs Benedict","rarity":"legendary","id":"eggs-benedict","subtitle":"Breakfast & Brunch","details":"A toasted English muffin topped with ham or bacon, a poached egg, and hollandaise sauce, its yolk running into the rich sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eggs_Benedict-01-cropped.jpg?width=1024"},{"name":"Full English Breakfast","rarity":"legendary","id":"full-english-breakfast","subtitle":"Breakfast & Brunch","details":"A hearty plate of fried eggs, bacon, sausages, beans, mushrooms, tomatoes, and toast, cooked together as one generous meal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Full-English-North-Wales.jpg?width=1024"},{"name":"Belgian Waffles","rarity":"epic","id":"belgian-waffles","subtitle":"Breakfast & Brunch","details":"Thick, deep-pocketed waffles with a crisp shell and fluffy middle, served with berries, whipped cream, or warm maple syrup.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belgian_waffle.jpg?width=1024"},{"name":"Buttermilk Pancakes","rarity":"epic","id":"buttermilk-pancakes","subtitle":"Breakfast & Brunch","details":"A tall stack of fluffy griddled pancakes made tangy with buttermilk, served with melting butter and warm maple syrup on top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pancakes_with_Berries_%28Unsplash%29.jpg?width=1024"},{"name":"French Toast","rarity":"epic","id":"french-toast","subtitle":"Breakfast & Brunch","details":"Thick slices of bread soaked in cinnamon egg custard and fried in butter until golden, served with syrup, berries, or sugar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FRENCH_TOAST_-_Keys_%26_Co._2025-03-27.jpg?width=1024"},{"name":"Shakshuka","rarity":"epic","id":"shakshuka","subtitle":"Breakfast & Brunch","details":"Eggs poached directly in a spiced tomato and pepper sauce with cumin and paprika, served bubbling in the pan with crusty bread.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Liat_Portal_for_Foodie_Disorder_-_Classic_Red_Shakshuka_with_Egg.jpg?width=800"},{"name":"Huevos Rancheros","rarity":"rare","id":"huevos-rancheros","subtitle":"Breakfast & Brunch","details":"Fried eggs served on warm corn tortillas under a cooked tomato and chile salsa, often with refried beans and avocado alongside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/04_Huevos_Rancheros_-_Mesa_Coyoacan.jpg?width=1024"},{"name":"Chicken and Waffles","rarity":"rare","id":"chicken-and-waffles","subtitle":"Breakfast & Brunch","details":"Crisp fried chicken served over a golden waffle, the savory crunch and sweet maple syrup making its signature contrast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chicken_and_Waffles.jpg?width=1024"},{"name":"Quiche Lorraine","rarity":"rare","id":"quiche-lorraine","subtitle":"Breakfast & Brunch","details":"A savory tart of eggs and cream baked in a crisp pastry shell with bacon lardons, named for the Lorraine region of France.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/54._Quiche_lorraine.jpg?width=1024"},{"name":"Avocado Toast","rarity":"rare","id":"avocado-toast","subtitle":"Breakfast & Brunch","details":"Thick toast spread with smashed seasoned avocado, often finished with chili flakes, seeds, herbs, or a soft cooked egg on top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Avocado_toast_with_sesame_seeds.jpg?width=1024"},{"name":"French Omelette","rarity":"rare","id":"french-omelette","subtitle":"Breakfast & Brunch","details":"Eggs whisked and gently rolled in butter into a pale, tender fold with a soft, just-set center and no browning on the surface.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FoodOmelete.jpg?width=1024"},{"name":"Frittata","rarity":"rare","id":"frittata","subtitle":"Breakfast & Brunch","details":"An Italian open-faced egg dish cooked slowly with vegetables, cheese, or meats, finished firm enough to slice into wedges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frittata02.jpg?width=1024"},{"name":"Breakfast Burrito","rarity":"uncommon","id":"breakfast-burrito","subtitle":"Breakfast & Brunch","details":"A warm flour tortilla wrapped around scrambled eggs, potatoes, cheese, and peppers or meat, griddled until the outside crisps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bacon_Kale_Breakfast_Burrito_%288429773809%29.jpg?width=1024"},{"name":"Eggs Florentine","rarity":"uncommon","id":"eggs-florentine","subtitle":"Breakfast & Brunch","details":"A poached egg and wilted spinach on a toasted English muffin under hollandaise, a green counterpart to eggs Benedict.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_wordridden_2508509760--Eggs_Florentine.jpg?width=1024"},{"name":"Corned Beef Hash","rarity":"uncommon","id":"corned-beef-hash","subtitle":"Breakfast & Brunch","details":"Chopped corned beef and potatoes fried together until crisp at the edges, often crowned with a fried or poached egg on top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hash_%284106225932%29.jpg?width=1024"},{"name":"Hash Browns","rarity":"uncommon","id":"hash-browns","subtitle":"Breakfast & Brunch","details":"Shredded potatoes pan-fried into a crisp golden cake with a soft middle, seasoned simply and served straight from the skillet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hash_browns_on_white_plate.jpg?width=1024"},{"name":"Masala Dosa","rarity":"uncommon","id":"masala-dosa","subtitle":"Breakfast & Brunch","details":"A crisp, lacy fermented rice crepe wrapped around spiced potato filling, served with sambar and coconut chutney for dipping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_plate_of_South_Indian_Masala_Dosa.jpg?width=1024"},{"name":"Congee","rarity":"uncommon","id":"congee","subtitle":"Breakfast & Brunch","details":"Rice simmered in abundant water or broth until it breaks down into a silky porridge, topped with ginger, scallions, or egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chinese_rice_porridge_with_toppings_by_iandeth.jpg?width=1024"},{"name":"Chilaquiles","rarity":"uncommon","id":"chilaquiles","subtitle":"Breakfast & Brunch","details":"Fried corn tortilla pieces simmered briefly in red or green salsa and topped with egg, cheese, crema, onion, and avocado.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chilaquiles_Rojos.JPG?width=1024"},{"name":"Menemen","rarity":"uncommon","id":"menemen","subtitle":"Breakfast & Brunch","details":"A Turkish dish of eggs gently scrambled into simmering tomatoes, peppers, and spices, cooked soft and eaten with bread.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Menemen_in_pan.jpg?width=1024"},{"name":"Idli with Sambar","rarity":"uncommon","id":"idli-with-sambar","subtitle":"Breakfast & Brunch","details":"Steamed South Indian rice cakes, soft and spongy, served with hot lentil sambar and chutneys for soaking up every bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Idli-sambar_and_coffee_at_Udupi_Upahar%2C_Wilson_Garden%2C_Bangalore_%282025-09-19%29.jpg?width=1024"},{"name":"Diner Breakfast Plate","rarity":"uncommon","id":"diner-breakfast-plate","subtitle":"Breakfast & Brunch","details":"The classic counter plate of fried eggs, crisp bacon, buttered toast, and golden potatoes, served hot and generously portioned.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Breakfast_in_Australia%3B_bacon_and_fried_eggs_on_toast.jpg?width=1024"},{"name":"Bagel with Cream Cheese","rarity":"common","id":"bagel-with-cream-cheese","subtitle":"Breakfast & Brunch","details":"A chewy boiled-and-baked bagel sliced and spread thickly with cream cheese, the simplest form of a deli breakfast staple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bagel_with_cream_cheese_-_Massachusetts.jpg?width=1024"},{"name":"Oatmeal Porridge","rarity":"common","id":"oatmeal-porridge","subtitle":"Breakfast & Brunch","details":"Rolled oats simmered in water or milk into a thick, warming porridge, sweetened and topped with fruit, nuts, or brown sugar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banana_blueberry_oatmeal.jpg?width=1024"},{"name":"Yogurt and Granola Parfait","rarity":"common","id":"yogurt-and-granola-parfait","subtitle":"Breakfast & Brunch","details":"Layers of creamy yogurt, crunchy granola, and fresh berries built in a glass, alternating smooth, crisp, and juicy textures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-2020-01-13_Fruit_and_Yogurt_Breakfast_Parfait%2C_Trimingham.JPG?width=1024"},{"name":"Acai Bowl","rarity":"common","id":"acai-bowl","subtitle":"Breakfast & Brunch","details":"Thick blended acai puree spooned into a bowl and topped with granola, banana, berries, and coconut in neat, colorful rows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acai_bowl_%2843779425762%29.jpg?width=1024"},{"name":"Breakfast Sandwich","rarity":"common","id":"breakfast-sandwich","subtitle":"Breakfast & Brunch","details":"Egg, cheese, and often bacon or sausage tucked into a biscuit, muffin, or roll, wrapped warm for eating on the move.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ham%2C_egg_and_cheese_muffin.jpg?width=1024"},{"name":"Dutch Baby Pancake","rarity":"common","id":"dutch-baby-pancake","subtitle":"Breakfast & Brunch","details":"A puffy oven-baked pancake that rises dramatically in a hot skillet, then settles into a custardy bowl for fruit and sugar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2-22-2025_Dutch_baby_pancake_%2812_of_12%29.jpg?width=1024"},{"name":"Sweet Crepes","rarity":"common","id":"sweet-crepes","subtitle":"Breakfast & Brunch","details":"Paper-thin pancakes folded or rolled around sweet fillings such as chocolate spread, berries, lemon sugar, or whipped cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_dessert_cr%C3%AApe_with_candied_nuts_and_whipped_cream.jpeg?width=1024"},{"name":"Cheese Blintzes","rarity":"common","id":"cheese-blintzes","subtitle":"Breakfast & Brunch","details":"Thin crepes wrapped around sweetened cheese filling, pan-fried until golden and served with sour cream or fruit sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese_blintzes_with_blackberries.jpg?width=1024"},{"name":"Kaiserschmarrn","rarity":"common","id":"kaiserschmarrn","subtitle":"Breakfast & Brunch","details":"An Austrian pancake torn into fluffy pieces, caramelized in butter, dusted with sugar, and served with fruit compote.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2015_0731_Kaiserschmarrn_Apfelso%C3%9Fe_Edelweissh%C3%BCtte_S%C3%B6lden.jpg?width=1024"},{"name":"Rösti","rarity":"common","id":"rosti","subtitle":"Breakfast & Brunch","details":"A Swiss cake of grated potato pan-fried until the outside turns deeply crisp and golden while the inside stays tender.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%B6sti_auf_blauem_Teller.jpg?width=1024"},{"name":"Bubble and Squeak","rarity":"common","id":"bubble-and-squeak","subtitle":"Breakfast & Brunch","details":"A British fry-up of leftover potatoes and cabbage mashed and pan-fried into a crisp cake, named for the sounds it makes cooking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bubble_%26_Squeak_Special_and_hot_chocolate_-_Monty%27s_2025-12-05.jpg?width=1024"},{"name":"Kedgeree","rarity":"common","id":"kedgeree","subtitle":"Breakfast & Brunch","details":"A curried rice dish with flaked smoked fish, boiled eggs, and parsley, seasoned warmly and served as a hearty breakfast plate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kedgeree.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
